package com.bank.check.db;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// Enforces CHECK rules on every insert/update, for every caller.
public class CheckedStore {
    private static final Logger log = Logger.getLogger(CheckedStore.class.getName());
    private static final Set<String> VALID_STATUS = Set.of("ACTIVE","INACTIVE","FROZEN");
    private final Map<String, BigDecimal> balances = new HashMap<>();
    private final Map<String, String> statuses = new HashMap<>();

    private void checkBalance(BigDecimal b) {
        // Three-valued logic: null passes (unknown ≠ false).
        if (b != null && b.compareTo(BigDecimal.ZERO) < 0)
            throw new IllegalStateException("CHECK chk_balance_nonneg violated: balance < 0");
    }
    private void checkStatus(String s) {
        if (s != null && !VALID_STATUS.contains(s))
            throw new IllegalStateException("CHECK chk_status violated: status=" + s);
    }

    public void insert(String id, BigDecimal balance, String status) {
        checkBalance(balance); checkStatus(status);
        balances.put(id, balance); statuses.put(id, status);
        log.info(() -> "inserted " + id + " balance=" + balance + " status=" + status);
    }

    // Applies on UPDATE too — a withdrawal that would go negative is rejected.
    public void updateBalance(String id, BigDecimal newBalance) {
        checkBalance(newBalance);
        balances.put(id, newBalance);
        log.info(() -> "updated " + id + " balance=" + newBalance);
    }

    public void updateStatus(String id, String status) {
        checkStatus(status);
        statuses.put(id, status);
        log.info(() -> "updated " + id + " status=" + status);
    }

    public BigDecimal balance(String id) { return balances.get(id); }
}
