package com.bank.check.service;

import com.bank.check.db.CheckedStore;
import java.math.BigDecimal;
import java.util.logging.Logger;

public class AccountService {
    private static final Logger log = Logger.getLogger(AccountService.class.getName());
    private final CheckedStore db;
    public AccountService(CheckedStore db) { this.db = db; }

    // The service does NOT pre-check balance — relying on the DB CHECK as the guard.
    public void withdraw(String id, BigDecimal amount) {
        BigDecimal after = db.balance(id).subtract(amount);
        db.updateBalance(id, after);   // DB CHECK rejects if this goes negative
        log.info(() -> "withdraw " + amount + " from " + id + " → " + after);
    }
}
