package com.bank.check;

import com.bank.check.db.CheckedStore;
import com.bank.check.service.AccountService;
import java.math.BigDecimal;
import java.util.logging.*;

public class CheckDemo {
    private static final Logger log = Logger.getLogger(CheckDemo.class.getName());

    public static void main(String[] args) {
        setupLogger();
        CheckedStore db = new CheckedStore();
        db.insert("SAV2001", new BigDecimal("1000000"), "ACTIVE");
        AccountService svc = new AccountService(db);

        tryOp("valid withdrawal (within balance)", () -> svc.withdraw("SAV2001", new BigDecimal("50000")));
        tryOp("over-withdrawal (CHECK balance>=0 fires)", () -> svc.withdraw("SAV2001", new BigDecimal("99999999")));
        tryOp("bad status value (CHECK status fires)", () -> db.updateStatus("SAV2001", "BLAH"));
        tryOp("valid status change", () -> db.updateStatus("SAV2001", "FROZEN"));
        tryOp("direct SQL-style write with null balance (passes: 3-valued logic)",
              () -> db.insert("TMP0001", null, "ACTIVE"));
        tryOp("direct SQL-style write negative balance (CHECK still catches it)",
              () -> db.insert("BAD0001", new BigDecimal("-1"), "ACTIVE"));
    }

    private static void tryOp(String label, Runnable r) {
        try { r.run(); } catch (RuntimeException ex) { log.severe(label + " → REJECTED: " + ex.getMessage()); }
    }

    private static void setupLogger() {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch); root.setLevel(Level.ALL);
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
